<script setup>
import {ref,computed,onMounted,onBeforeUnmount} from 'vue';
import * as T from 'three';
import land from './game/earth-land.json';
const fallback=ref(false);const props=defineProps({from:Object,to:Object});const emit=defineEmits(['finish']);const canvas=ref(null),progress=ref(0),depart=ref({x:0,y:0}),arrival=ref({x:0,y:0});let renderer,scene,geometry,texture,material,frame,started,observer,hiddenAt,pausedMs=0,disposed=false;
const status=computed(()=>progress.value<.23?'DEPARTING':progress.value<.79?'IN TRANSIT':'ARRIVING');
const mapPoint=c=>({x:(c.lon+180)*2,y:(90-c.lat)*2});const mapLand=land.map(ring=>'M'+ring.map(([lon,lat])=>`${((lon+180)*2).toFixed(1)},${((90-lat)*2).toFixed(1)}`).join('L')+'Z');
const mapRoute=computed(()=>{const a=mapPoint(props.from),b=mapPoint(props.to);return `M${a.x},${a.y} Q${(a.x+b.x)/2},${Math.min(a.y,b.y)-40} ${b.x},${b.y}`;});
const airportCountry=computed(()=>progress.value<.5?props.from:props.to);
const ll=(lat,lon,r=1)=>{const a=lat*Math.PI/180,b=lon*Math.PI/180;return new T.Vector3(Math.cos(a)*Math.sin(b),Math.sin(a),Math.cos(a)*Math.cos(b)).multiplyScalar(r);};
function visibility(){if(document.hidden)hiddenAt=performance.now();else if(hiddenAt){pausedMs+=performance.now()-hiddenAt;hiddenAt=null;}}
onMounted(()=>{
 started=performance.now();hiddenAt=document.hidden?started:null;document.addEventListener('visibilitychange',visibility);try{
 const target=canvas.value;renderer=new T.WebGLRenderer({canvas:target,antialias:true,alpha:true,powerPreference:'low-power'});renderer.setPixelRatio(Math.min(devicePixelRatio,1.5));renderer.outputColorSpace=T.SRGBColorSpace;scene=new T.Scene();const camera=new T.PerspectiveCamera(37,1,.1,10);camera.position.z=3.8;
 const atlas=document.createElement('canvas');atlas.width=1024;atlas.height=512;const c=atlas.getContext('2d');c.fillStyle='#6d91a0';c.fillRect(0,0,1024,512);c.fillStyle='#bec9b2';c.strokeStyle='#a7bcae';c.lineWidth=.7;for(const ring of land){c.beginPath();ring.forEach(([lon,lat],i)=>{const x=(lon+180)/360*1024,y=(90-lat)/180*512;i?c.lineTo(x,y):c.moveTo(x,y);});c.closePath();c.fill();c.stroke();}
 texture=new T.CanvasTexture(atlas);texture.colorSpace=T.SRGBColorSpace;geometry=new T.SphereGeometry(1,64,40);const uv=geometry.attributes.uv,p=geometry.attributes.position;for(let i=0;i<p.count;i++)uv.setXY(i,(Math.atan2(p.getX(i),p.getZ(i))+Math.PI)/(2*Math.PI),.5+Math.asin(p.getY(i))/Math.PI);material=new T.MeshPhongMaterial({map:texture,shininess:11,specular:'#647c80'});
 const group=new T.Group();scene.add(group);group.add(new T.Mesh(geometry,material));scene.add(new T.AmbientLight('#b8d7e5',1.4));const key=new T.DirectionalLight('#fff7e9',2.5);key.position.set(-3,4,5);scene.add(key);
 const from=ll(props.from.lat,props.from.lon,1.02),to=ll(props.to.lat,props.to.lon,1.02),mid=from.clone().add(to).normalize();group.quaternion.setFromUnitVectors(mid,new T.Vector3(0,.10,1).normalize());
 const pinMaterial=new T.MeshBasicMaterial({color:'#eaf8f7'}),pinGeometry=new T.SphereGeometry(.018,12,8);for(const point of [from,to]){const pin=new T.Mesh(pinGeometry,pinMaterial);pin.position.copy(point);group.add(pin);}
 const angle=from.angleTo(to),route=t=>{if(angle<.0001)return from.clone();return from.clone().multiplyScalar(Math.sin((1-t)*angle)).addScaledVector(to,Math.sin(t*angle)).multiplyScalar(1/Math.sin(angle)).normalize().multiplyScalar(1.035+Math.sin(t*Math.PI)*.07);};
 const dots=[];for(let i=0;i<=40;i++)dots.push(...route(i/40).toArray());const dotGeometry=new T.BufferGeometry();dotGeometry.setAttribute('position',new T.Float32BufferAttribute(dots,3));const dotMaterial=new T.PointsMaterial({color:'#101b20',size:.011,sizeAttenuation:true});group.add(new T.Points(dotGeometry,dotMaterial));
 const shape=new T.Shape();shape.moveTo(0,.07);shape.lineTo(.013,.015);shape.lineTo(.06,-.016);shape.lineTo(.06,-.03);shape.lineTo(.013,-.017);shape.lineTo(.012,-.055);shape.lineTo(.028,-.067);shape.lineTo(.028,-.078);shape.lineTo(0,-.065);shape.lineTo(-.028,-.078);shape.lineTo(-.028,-.067);shape.lineTo(-.012,-.055);shape.lineTo(-.013,-.017);shape.lineTo(-.06,-.03);shape.lineTo(-.06,-.016);shape.lineTo(-.013,.015);shape.closePath();const planeGeometry=new T.ShapeGeometry(shape),planeMaterial=new T.MeshBasicMaterial({color:'#f9f6e7',side:T.DoubleSide});const plane=new T.Mesh(planeGeometry,planeMaterial);group.add(plane);
 const label=v=>{const p=v.clone().applyQuaternion(group.quaternion).project(camera);return{x:(p.x+1)*50,y:(1-p.y)*50};};
 const resize=()=>{if(disposed)return;const box=target.getBoundingClientRect();renderer.setSize(Math.max(1,box.width),Math.max(1,box.height),false);camera.aspect=box.width/Math.max(1,box.height);camera.updateProjectionMatrix();camera.updateMatrixWorld(true);depart.value=label(from);arrival.value=label(to);};observer=new ResizeObserver(resize);observer.observe(target);resize();
 const normal=new T.Vector3(),up=new T.Vector3(),basis=new T.Matrix4();function draw(now){if(disposed)return;frame=requestAnimationFrame(draw);if(document.hidden)return;const t=Math.min(1,(now-started-pausedMs)/10000);progress.value=t;const travel=T.MathUtils.smoothstep(t,.23,.79),pos=route(travel);plane.position.copy(pos);normal.copy(pos).normalize();up.copy(route(Math.min(.999,travel+.004))).sub(route(Math.max(.001,travel-.004))).normalize();if(up.lengthSq()<.01)up.set(0,1,0);const right=new T.Vector3().crossVectors(up,normal).normalize();up.crossVectors(normal,right).normalize();basis.makeBasis(right,up,normal);plane.quaternion.setFromRotationMatrix(basis);renderer.render(scene,camera);if(t>=1){cancelAnimationFrame(frame);emit('finish');}}
 frame=requestAnimationFrame(draw);
 }catch{fallback.value=true;const a=mapPoint(props.from),b=mapPoint(props.to);depart.value={x:a.x/7.2,y:a.y/3.6};arrival.value={x:b.x/7.2,y:b.y/3.6};const tick=now=>{if(disposed)return;if(!document.hidden){progress.value=Math.min(1,(now-started-pausedMs)/10000);if(progress.value>=1){emit('finish');return;}}frame=requestAnimationFrame(tick);};frame=requestAnimationFrame(tick);}
});
onBeforeUnmount(()=>{disposed=true;cancelAnimationFrame(frame);observer?.disconnect();document.removeEventListener('visibilitychange',visibility);const geometries=new Set([geometry].filter(Boolean)),materials=new Set([material].filter(Boolean)),textures=new Set([texture].filter(Boolean));scene?.traverse(o=>{if(o.geometry)geometries.add(o.geometry);if(o.material)materials.add(o.material);});for(const m of materials)for(const v of Object.values(m))if(v?.isTexture)textures.add(v);for(const g of geometries)g.dispose();for(const t of textures)t.dispose();for(const m of materials)m.dispose();renderer?.dispose();renderer?.forceContextLoss();});
</script>
<template><section class="travel-screen" :class="status.toLowerCase().replaceAll(' ','-')"><header><span class="eyebrow">KTD / INTERNATIONAL ASSIGNMENTS</span><span>{{status}} <i class="live-dot"></i></span></header><div class="travel-globe"><div class="airport-scene" v-if="status!=='IN TRANSIT'" :key="status"><div class="airport-moon"></div><div class="airport-skyline"><i v-for="n in 16" :key="n" :style="{height:(22+n%5*11)+'%'}"></i></div><div class="airport-runway"><i v-for="n in 14" :key="n"></i></div><svg class="cinematic-plane" viewBox="0 0 400 140" aria-label="Airplane departing or landing"><path d="M8 87L86 79 47 24 66 23 140 74 286 66Q347 60 380 84L389 91 375 98 143 102 83 126 63 126 93 101 17 101Z" fill="#e4edf0"/><path d="M90 80L72 33 96 33 138 76M187 98L132 136 164 136 240 97" fill="#7d9fae"/><path d="M321 73L338 83 361 84" stroke="#173b50" stroke-width="5" fill="none"/><path d="M149 83H302" stroke="#173b50" stroke-width="5" stroke-dasharray="5 7"/><path d="M11 100H369" stroke="#779aaa" stroke-width="3"/></svg><div class="airport-caption"><small>{{status==='DEPARTING'?'LEAVING':'TOUCHDOWN'}} / {{airportCountry.city.toUpperCase()}}</small><h2>{{airportCountry.name}}</h2></div></div><canvas v-show="!fallback" ref="canvas" aria-label="Earth with a dotted flight route and moving airplane"></canvas><svg v-if="fallback" class="flight-map-fallback" viewBox="0 0 720 360" preserveAspectRatio="none" role="img" aria-label="World map and dotted airplane route"><rect width="720" height="360" fill="#6d91a0"/><path v-for="(d,i) in mapLand" :key="i" :d="d" fill="#bec9b2"/><path id="fallback-flight-route" :d="mapRoute" fill="none" stroke="#101b20" stroke-width="2.5" stroke-dasharray="2 5"/><circle v-for="c in [from,to]" :key="c.id" :cx="mapPoint(c).x" :cy="mapPoint(c).y" r="4" fill="#ecf8f4"/><text fill="#fff" font-size="18">✈<animateMotion dur="5.6s" begin="2.3s" fill="freeze" rotate="auto"><mpath href="#fallback-flight-route"/></animateMotion></text></svg><span class="travel-pin departure" :style="{left:depart.x+'%',top:depart.y+'%'}">{{from.name}}</span><span class="travel-pin arrival" :style="{left:arrival.x+'%',top:arrival.y+'%'}">{{to.name}}</span></div><div class="travel-itinerary"><div><small>DEPARTURE / {{from.city}}</small><h2>{{from.name}}</h2></div><span class="flight-arrow">✈</span><div><small>ARRIVAL / {{to.city}}</small><h2>{{to.name}}</h2></div></div><p>{{to.hospital}} Medical Center · next assignment</p><div class="flight-progress"><i :style="{width:progress*100+'%'}"></i></div><button @click="emit('finish')">Skip flight →</button></section></template>

<style scoped>
.flight-map-fallback{width:100%;height:100%}.airport-scene{position:absolute;inset:0;z-index:3;overflow:hidden;background:linear-gradient(#081424,#183c51 72%,#1c2933 73%);border:1px solid #91c6d630;animation:airport-fade .35s both}.airport-moon{position:absolute;right:17%;top:13%;width:55px;height:55px;border-radius:50%;background:#d5e5dc;box-shadow:0 0 60px #b2d5dd30}.airport-skyline{position:absolute;inset:35% 0 23%;display:flex;align-items:end;gap:1%;opacity:.65}.airport-skyline i{background:#091e2b;width:7%;border-top:2px solid #8bbfd233}.airport-runway{position:absolute;bottom:12%;left:-10%;width:120%;height:3px;background:#f3c275;display:flex;justify-content:space-around;transform:rotate(-4deg)}.airport-runway i{width:6px;height:5px;background:#ffe0a3;box-shadow:0 0 15px #ffc54e}.cinematic-plane{position:absolute;width:33%;left:-35%;bottom:16%;filter:drop-shadow(0 10px 7px #0007);animation:takeoff 2.3s linear forwards}.arriving .cinematic-plane{animation:landing 2.1s ease-out forwards}.airport-caption{position:absolute;left:5%;top:7%;color:#e2f0f4}.airport-caption small{font:11px monospace;letter-spacing:.2em}.airport-caption h2{font-size:clamp(26px,5vw,60px);margin:.25em 0}@keyframes takeoff{0%{left:-35%;bottom:14%;transform:rotate(0)}45%{bottom:18%;transform:rotate(-7deg)}100%{left:102%;bottom:65%;transform:rotate(-12deg)}}@keyframes landing{0%{left:-35%;bottom:57%;transform:rotate(10deg)}75%{bottom:17%;transform:rotate(0)}100%{left:105%;bottom:16%;transform:rotate(0)}}@keyframes airport-fade{from{opacity:0}to{opacity:1}}
</style>
